import React from "react";

export default function AdminTest({ logout }) {
  return (
    <div
      style={{
        height: '100vh',
        margin: 0,
        padding: 0,
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        fontSize: '1.5rem',
      }}
    >
      <p>Admin Page - No layout loaded</p>
      <button
        onClick={logout}
        style={{
          marginTop: '20px',
          padding: '10px 20px',
          fontSize: '1rem',
          cursor: 'pointer',
        }}
      >
        Logout
      </button>
    </div>
  );
}
